}

solution.Solution.java:
public class Solution {
    static double toCelsius(double fahrenheit) {
        return (fahrenheit - 32) * 5 / 9;
    }

    static double average(int a, int b, int c) {
        return (a + b + c) / 3.0;
    }

    static int parseOrDefault(String text, int fallback) {
        try {
            return Integer.parseInt(text.trim());
        } catch (NumberFormatException e) {
            return fallback;
        }
    }

    static long toCents(double euros) {
        return Math.round(euros * 100);
    }
}

hints:
`Integer.parseInt` throws a `NumberFormatException` when the text is not a whole number that fits in an `int`. Catch it to use a fallback instead, and call `text.trim()` first to remove the spaces around the number:

```java-norun
try {
    double d = Double.parseDouble(input.trim());   // jumps to catch if input is not a number
    System.out.println(d * 2);
} catch (NumberFormatException e) {
    System.out.println("not a number");             // runs instead
}
```

unitTests:
test("Fahrenheit to Celsius", () -> {
    checkNear(Solution.toCelsius(212), 100);
    checkNear(Solution.toCelsius(32), 0);
    checkNear(Solution.toCelsius(-40), -40);
    checkNear(Solution.toCelsius(98.6), 37);
});

test("an exact average", () -> {
    checkNear(Solution.average(1, 2, 2), 5.0 / 3);
    checkNear(Solution.average(10, 20, 30), 20);
    checkNear(Solution.average(-1, 0, 0), -1.0 / 3);
});

test("parsing safely", () -> {
    checkEq(Solution.parseOrDefault("42", 0), 42);
    checkEq(Solution.parseOrDefault(" -7 ", 0), -7);
    checkEq(Solution.parseOrDefault("4x", 5), 5);
    checkEq(Solution.parseOrDefault("", 9), 9);
    checkEq(Solution.parseOrDefault("3.5", 1), 1);
    checkEq(Solution.parseOrDefault("99999999999", 2), 2);
});

test("euros to cents", () -> {
    checkEq(Solution.toCents(19.99), 1999L);
    checkEq(Solution.toCents(0.29), 29L);
    checkEq(Solution.toCents(0.07), 7L);
    checkEq(Solution.toCents(1234.5), 123450L);
});

